-- Ten more articles, from docs/CONTENT_PLAN.md and the fact sheet there. Stored the same way as the three in 20261103000006:
-- live, with the draft equal to the live columns, so the admin blog shows no unpublished changes. Staff can edit or
-- unpublish them at /admin/blog. A slug someone has already used is left alone. Newest first on /blog.

insert into public.blog_posts (slug, draft, is_live, title, seo_title, description, kicker, summary, body, read_minutes, published_at, updated_at, created_at, draft_saved_at) values (
  'studying-at-university-in-vietnam', $j${"title": "Good at Vietnamese, Struggling at University: Why Class Is a Different Language", "seo_title": "Studying at University in Vietnamese", "description": "You passed your Vietnamese course, but lectures and exams feel impossible. Why grades can fall at a Vietnamese university, and how to close the gap.", "kicker": "Studying in Vietnam", "summary": "Passing a Vietnamese course does not mean you can follow a lecture or write an exam answer in Vietnamese. University asks for faster, more formal language than most courses teach, and it is mostly learned by using it with Vietnamese people. If your grades are falling, your subject may not be the problem.", "cover_url": null, "cover_alt": null, "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "A situation many international students will recognise"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "This is a typical story rather than one real person's, and the name is made up. Daniel studied Vietnamese for over a year. He did well in his language course, and he could order food, chat with his teacher and read short articles. He felt ready, so he enrolled in a degree taught in Vietnamese at a university in Vietnam."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "In his home country, Daniel was a strong student. By the middle of his first semester, his marks were sliding. He understood the ideas when he read about them in English, but he lost the thread in lectures. He stayed quiet in discussions and went into exams knowing the answers without being able to write them fast enough."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "His problem was not intelligence or effort. In all that time, he had barely talked with any Vietnamese people apart from his teacher. He knew Vietnamese as a school subject, but he had never used it to get anything done."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why good test scores can hide the problem"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A language course is designed to be understood. The teacher slows down, chooses words you already know and is used to the mistakes foreigners make. A lecture is designed to teach the subject, and it assumes you already have the language. Several things change at once:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Speed.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A lecturer speaks to native speakers at a normal pace, and may switch to examples or jokes without warning."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Vocabulary.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Your course taught you market and restaurant words, but your degree needs the words of economics, nursing or engineering."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Accent.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " You may have learned one accent, while your lecturers and classmates come from the north, centre and south of the country."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Formal register.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A sentence that is fine in a café can sound childish in an essay."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Time pressure.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " In an exam you must read the question, plan an answer and write it in Vietnamese, with every tone mark, before the time runs out."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What falling grades often mean"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Marks measure your subject knowledge and your language at the same moment, so you cannot always tell which one failed. Try a quick test: take an exam question you got wrong and explain the answer in your strongest language. If you can do it easily, your subject knowledge is fine, and language is what cost you the marks. That is good news, because a language gap can be worked on directly."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The words a student needs first"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Learn these early. They come up in almost every course, and many beginner books leave them out."}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tín chỉ", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": credit"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "học phần", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": course module"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "giáo trình", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": course textbook"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "điểm danh", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": taking attendance"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "bài tập nhóm", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": group assignment"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "thuyết trình", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": presentation"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "thi giữa kỳ", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "thi cuối kỳ", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": midterm and final exam"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "ôn thi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": revising for an exam"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You also need a few sentences for speaking to a lecturer. Use "}, {"type": "text", "text": "thầy", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " for a male teacher, "}, {"type": "text", "text": "cô", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " for a female teacher and "}, {"type": "text", "text": "em", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " for yourself:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Thưa thầy, em chưa hiểu phần này ạ.", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " = Excuse me, sir, I don't understand this part yet."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cô có thể giải thích lại được không ạ?", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " = Could you explain that again, please?"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Read more about these word choices in our guide to "}, {"type": "text", "text": "Vietnamese pronouns", "marks": [{"type": "link", "attrs": {"href": "/blog/vietnamese-pronouns-explained"}}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Everyday Vietnamese is not exam Vietnamese"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Here is the kind of sentence a learner might write in a business exam. Everyone would understand it, but it would not earn full marks:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Em nghĩ công ty này tốt vì nó làm nhiều tiền.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Theo em, công ty này hoạt động hiệu quả vì lợi nhuận cao.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Both mean roughly \"In my view, this company does well because it makes a lot of money\". The first is how you might say it to a friend. The second has words a lecturer expects to see: "}, {"type": "text", "text": "hoạt động hiệu quả", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"operates efficiently\") and "}, {"type": "text", "text": "lợi nhuận", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"profit\"). Nobody learns that difference from a grammar table. You learn it when someone who knows the language shows you the better sentence, using the very thing you wrote."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to close the gap"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Write about your course every day.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " After each class, write three sentences on what you learned, in Vietnamese. This practises the subject and the language at the same time."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Get those sentences corrected.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Ask for the version a good student would hand in, not only for your grammar to be fixed."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Make Vietnamese friends in your class.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Join the class group chat and read it, even when you have nothing to say. Offer your own language in return for help with notes. Many students would welcome that."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Prepare before the lecture.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Read the chapter first and list the new words. It is much easier to follow speech when you already know what is coming."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Practise writing against a clock.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Answer an old exam question in the time allowed, then have your answer checked."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ask for help early.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Tell your lecturer or international student office what is happening before your exams. Ask whether support is available, as this varies between universities."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Where The Fluency Talks helps, and where it doesn't"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": " is a free language exchange where you can chat with native Vietnamese speakers in writing. For a student like Daniel, that covers an important part of the problem:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "You can use Vietnamese with real people every day, from your phone, without waiting for a class."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A partner can edit your sentence where you wrote it, so you see exactly what changed. That suits essay and exam writing."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Corrections you accept go into your phrasebook, so your own mistakes and subject words become your revision list."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "If you are stuck on one sentence, you can spend 50 points on a bounty to show it to qualified speakers."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Please be realistic about two things. The chat is text only, so it will not train your ear for lectures. For that, you still need to spend time listening and talking with classmates. And no app can promise you better grades. What regular practice can do is give you what Daniel was missing: real use of the language, with people who tell you when something sounds wrong."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you are about to start a degree in Vietnamese, begin now rather than after your first bad result. "}, {"type": "text", "text": "Find a Vietnamese partner", "marks": [{"type": "link", "attrs": {"href": "/languages/vietnamese"}}]}, {"type": "text", "text": " and send your first sentence today."}]}]}}$j$::jsonb, true,
  $t$Good at Vietnamese, Struggling at University: Why Class Is a Different Language$t$, $t$Studying at University in Vietnamese$t$, $t$You passed your Vietnamese course, but lectures and exams feel impossible. Why grades can fall at a Vietnamese university, and how to close the gap.$t$, $t$Studying in Vietnam$t$, $t$Passing a Vietnamese course does not mean you can follow a lecture or write an exam answer in Vietnamese. University asks for faster, more formal language than most courses teach, and it is mostly learned by using it with Vietnamese people. If your grades are falling, your subject may not be the problem.$t$,
