paragraph", "content": [{"type": "text", "text": "Both mean roughly \"In my view, this company does well because it makes a lot of money\". The first is how you might say it to a friend. The second has words a lecturer expects to see: "}, {"type": "text", "text": "hoạt động hiệu quả", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"operates efficiently\") and "}, {"type": "text", "text": "lợi nhuận", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"profit\"). Nobody learns that difference from a grammar table. You learn it when someone who knows the language shows you the better sentence, using the very thing you wrote."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to close the gap"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Write about your course every day.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " After each class, write three sentences on what you learned, in Vietnamese. This practises the subject and the language at the same time."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Get those sentences corrected.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Ask for the version a good student would hand in, not only for your grammar to be fixed."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Make Vietnamese friends in your class.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Join the class group chat and read it, even when you have nothing to say. Offer your own language in return for help with notes. Many students would welcome that."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Prepare before the lecture.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Read the chapter first and list the new words. It is much easier to follow speech when you already know what is coming."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Practise writing against a clock.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Answer an old exam question in the time allowed, then have your answer checked."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ask for help early.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Tell your lecturer or international student office what is happening before your exams. Ask whether support is available, as this varies between universities."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Where The Fluency Talks helps, and where it doesn't"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": " is a free language exchange where you can chat with native Vietnamese speakers in writing. For a student like Daniel, that covers an important part of the problem:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "You can use Vietnamese with real people every day, from your phone, without waiting for a class."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A partner can edit your sentence where you wrote it, so you see exactly what changed. That suits essay and exam writing."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Corrections you accept go into your phrasebook, so your own mistakes and subject words become your revision list."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "If you are stuck on one sentence, you can spend 50 points on a bounty to show it to qualified speakers."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Please be realistic about two things. The chat is text only, so it will not train your ear for lectures. For that, you still need to spend time listening and talking with classmates. And no app can promise you better grades. What regular practice can do is give you what Daniel was missing: real use of the language, with people who tell you when something sounds wrong."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you are about to start a degree in Vietnamese, begin now rather than after your first bad result. "}, {"type": "text", "text": "Find a Vietnamese partner", "marks": [{"type": "link", "attrs": {"href": "/languages/vietnamese"}}]}, {"type": "text", "text": " and send your first sentence today."}]}]}$j$::jsonb, 6, now() - interval '0 minutes', now() - interval '0 minutes', now() - interval '0 minutes', now() - interval '0 minutes') on conflict (slug) do nothing;

insert into public.blog_posts (slug, draft, is_live, title, seo_title, description, kicker, summary, body, read_minutes, published_at, updated_at, created_at, draft_saved_at) values (
  'vietnamese-pronouns-explained', $j${"title": "Vietnamese Pronouns Explained: Why \"Xin chào\" Isn't Enough", "seo_title": "Vietnamese Pronouns Explained", "description": "In Vietnamese, you must know how you relate to someone before you can say hello. A clear guide to anh, chị, em and more, for English speakers.", "kicker": "Learning Vietnamese", "summary": "Vietnamese has no single word for \"I\" or \"you\" that suits every situation. You choose words based on age and relationship, usually family words such as anh, chị and em. Learn a few pairs and your greetings will sound much more natural than a textbook \"Xin chào\".", "cover_url": null, "cover_alt": null, "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What English speakers find surprising"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "In English, you can talk to your boss, your grandmother and a child using the same \"I\" and \"you\". In Vietnamese, you pick words according to who you both are. Most of those words mean family members, even between strangers. A waiter might call you \"older brother\", and you might call yourself \"younger sibling\"."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "That can sound complicated, but you only need the right pair. Once you choose how to address someone, the same pair works throughout the conversation."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why \"Xin chào\" isn't enough"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Xin chào", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " is correct, and every course teaches it first. It also sounds a little formal, like something from a sign or a broadcast. In daily life, people usually say "}, {"type": "text", "text": "chào", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " followed by the word for the person:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chào anh", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": hello, to a man a bit older than you"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chào chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": hello, to a woman a bit older than you"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chào em", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": hello, to someone younger than you"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "That small change shows you are paying attention to the person, and not only reciting a phrase."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The pairs to learn first"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Each word below can mean both \"I\" and \"you\", depending on who is speaking."}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "anh", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a man slightly older than the other person"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a woman slightly older than the other person"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "em", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": someone younger than the other person, of any gender"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "cô", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a female teacher, or a woman around your parents' age or a bit younger"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "thầy", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a male teacher"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "chú", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a man younger than your parents"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "bác", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a man or woman older than your parents"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "ông", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "bà", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": an elderly man and woman, like a grandfather and grandmother"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "cháu", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": yourself when you are talking to someone from your parents' or grandparents' generation"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "So if you are younger than a woman you are talking to, you are "}, {"type": "text", "text": "em", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and she is "}, {"type": "text", "text": "chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ":"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Em chào chị ạ. Em tên là Tom.", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Hello. My name is Tom."}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you later speak with her father, you change roles. You become "}, {"type": "text", "text": "cháu", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and he becomes "}, {"type": "text", "text": "bác", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " or "}, {"type": "text", "text": "chú", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What about tôi and bạn?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Books often teach "}, {"type": "text", "text": "tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " for \"I\" and "}, {"type": "text", "text": "bạn", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " for \"you\", and those are useful starting points. "}, {"type": "text", "text": "Bạn", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " works well between people of a similar age and with strangers online. "}, {"type": "text", "text": "Tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " is polite and neutral, and it is common in formal settings."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The catch is that "}, {"type": "text", "text": "tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " can sound distant among people who know each other. With friends your age, "}, {"type": "text", "text": "mình", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "bạn", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " feel warmer. If you keep saying "}, {"type": "text", "text": "tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " to a friend's older sister, it won't be wrong grammar, but it will sound stiff. A partner may correct it like this:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi cảm ơn chị.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Em cảm ơn chị ạ.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to choose when you don't know someone's age"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Vietnamese people often ask each other's age soon after meeting, and it is not considered rude in the way it can be elsewhere. The answer tells them which words to use. In practice, you can follow these rules:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "If you are unsure, choose respect.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Treat the other person as older. "}, {"type": "text", "text": "Anh", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " or "}, {"type": "text", "text": "chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " rarely offends."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Online with someone your age, use ", "marks": [{"type": "bold"}]}, {"type": "text", "text": "bạn", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and ", "marks": [{"type": "bold"}]}, {"type": "text", "text": "mình", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ".", "marks": [{"type": "bold"}]}, {"type": "text", "text": " They are safe and friendly."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Listen to what they call you.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " If someone calls themselves "}, {"type": "text", "text": "chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and you "}, {"type": "text", "text": "em", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ", reply with the same pair."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Simply ask.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " "}, {"type": "text", "text": "Mình nên gọi bạn là gì?", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " means \"What should I call you?\". People usually like being asked."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Add ạ when you want to be polite"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The small word "}, {"type": "text", "text": "ạ", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " at the end of a sentence adds respect, especially when you are speaking to someone older. Compare "}, {"type": "text", "text": "Em cảm ơn chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " with "}, {"type": "text", "text": "Em cảm ơn chị ạ", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ". Both mean \"thank you\", but the second sounds more polite. Use it with teachers, older people and anyone you want to show respect to."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Talking about other people"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "To say \"he\" or \"she\", add "}, {"type": "text", "text": "ấy", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " to the same family word: "}, {"type": "text", "text": "anh ấy", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "chị ấy", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "em ấy", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ". So the words you've just learned already cover most of what you need for talking about other people."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The best way to learn this"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Reading a list only gets you started. Pronouns become automatic when you make the choice many times with real people, and someone tells you when it sounds off. On "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", a native Vietnamese speaker can change your "}, {"type": "text", "text": "tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " to "}, {"type": "text", "text": "em", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " right in your message, and the corrected sentence goes into your phrasebook once you accept it."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Next, look at the "}, {"type": "text", "text": "common mistakes English speakers make in Vietnamese", "marks": [{"type": "link", "attrs": {"href": "/blog/common-vietnamese-mistakes"}}]}, {"type": "text", "text": ", or "}, {"type": "text", "text": "find a Vietnamese partner", "marks": [{"type": "link", "attrs": {"href": "/languages/vietnamese"}}]}, {"type": "text", "text": " and try your first "}, {"type": "text", "text": "Chào anh", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " or "}, {"type": "text", "text": "Chào chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": "."}]}]}}$j$::jsonb, true,
  $t$Vietnamese Pronouns Explained: Why "Xin chào" Isn't Enough$t$, $t$Vietnamese Pronouns Explained$t$, $t$In Vietnamese, you must know how you relate to someone before you can say hello. A clear guide to anh, chị, em and more, for English speakers.$t$, $t$Learning Vietnamese$t$, $t$Vietnamese has no single word for "I" or "you" that suits every situation. You choose words based on age and relationship, usually family words such as anh, chị and em. Learn a few pairs and your greetings will sound much more natural than a textbook "Xin chào".$t$,
  $j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What English speakers find surprising"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "In English, you can talk to your boss, your grandmother and a child using the same \"I\" and \"you\". In Vietnamese, you pick words according to who you both are. Most of those words mean family members, even between strangers. A waiter might call you \"older brother\", and you might call yourself \"younger sibling\"."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "That can sound complicated, but you only need the right pair. Once you choose how to address someone, the same pair works throughout the conversation."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why \"Xin chào\" isn't enough"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Xin chào", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " is correct, and every course teaches it first. It also sounds a little formal, like something from a sign or a broadcast. In daily life, people usually say "}, {"type": "text", "text": "chào", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " followed by the word for the person:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chào anh", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": hello, to a man a bit older than you"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chào chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": hello, to a woman a bit older than you"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chào em", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": hello, to someone younger than you"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "That small change shows you are paying attention to the person, and not only reciting a phrase."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The pairs to learn first"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Each word below can mean both \"I\" and \"you\", depending on who is speaking."}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "anh", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a man slightly older than the other person"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a woman slightly older than the other person"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "em", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": someone younger than the other person, of any gender"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "cô", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a female teacher, or a woman around your parents' age or a bit younger"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "thầy", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a male teacher"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "chú", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a man younger than your parents"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "bác", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": a man or woman older than your parents"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "ông", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "bà", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": an elderly man and woman, like a grandfather and grandmother"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "cháu", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": yourself when you are talking to someone from your parents' or grandparents' generation"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "So if you are younger than a woman you are talking to, you are "}, {"type": "text", "text": "em", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and she is "}, {"type": "text", "text": "chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ":"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Em chào chị ạ. Em tên là Tom.", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Hello. My name is Tom."}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you later speak with her father, you change roles. You become "}, {"type": "text", "text": "cháu", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and he becomes "}, {"type": "text", "text": "bác", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " or "}, {"type": "text", "text": "chú", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What about tôi and bạn?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Books often teach "}, {"type": "text", "text": "tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " for \"I\" and "}, {"type": "text", "text": "bạn", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " for \"you\", and those are useful starting points. "}, {"type": "text", "text": "Bạn", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " works well between people of a similar age and with strangers online. "}, {"type": "text", "text": "Tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " is polite and neutral, and it is common in formal settings."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The catch is that "}, {"type": "text", "text": "tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " can sound distant among people who know each other. With friends your age, "}, {"type": "text", "text": "mình", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "bạn", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " feel warmer. If you keep saying "}, {"type": "text", "text": "tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " to a friend's older sister, it won't be wrong grammar, but it will sound stiff. A partner may correct it like this:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi cảm ơn chị.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Em cảm ơn chị ạ.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to choose when you don't know someone's age"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Vietnamese people often ask each other's age soon after meeting, and it is not considered rude in the way it can be elsewhere. The answer tells them which words to use. In practice, you can follow these rules:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "If you are unsure, choose respect.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Treat the other person as older. "}, {"type": "text", "text": "Anh", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " or "}, {"type": "text", "text": "chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " rarely offends."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Online with someone your age, use ", "marks": [{"type": "bold"}]}, {"type": "text", "text": "bạn", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and ", "marks": [{"type": "bold"}]}, {"type": "text", "text": "mình", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ".", "marks": [{"type": "bold"}]}, {"type": "text", "text": " They are safe and friendly."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Listen to what they call you.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " If someone calls themselves "}, {"type": "text", "text": "chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " and you "}, {"type": "text", "text": "em", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ", reply with the same pair."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Simply ask.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " "}, {"type": "text", "text": "Mình nên gọi bạn là gì?", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " means \"What should I call you?\". People usually like being asked."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Add ạ when you want to be polite"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The small word "}, {"type": "text", "text": "ạ", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " at the end of a sentence adds respect, especially when you are speaking to someone older. Compare "}, {"type": "text", "text": "Em cảm ơn chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " with "}, {"type": "text", "text": "Em cảm ơn chị ạ", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ". Both mean \"thank you\", but the second sounds more polite. Use it with teachers, older people and anyone you want to show respect to."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Talking about other people"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "To say \"he\" or \"she\", add "}, {"type": "text", "text": "ấy", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " to the same family word: "}, {"type": "text", "text": "anh ấy", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "chị ấy", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "em ấy", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ". So the words you've just learned already cover most of what you need for talking about other people."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The best way to learn this"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Reading a list only gets you started. Pronouns become automatic when you make the choice many times with real people, and someone tells you when it sounds off. On "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", a native Vietnamese speaker can change your "}, {"type": "text", "text": "tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " to "}, {"type": "text", "text": "em", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " right in your message, and the corrected sentence goes into your phrasebook once you accept it."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Next, look at the "}, {"type": "text", "text": "common mistakes English speakers make in Vietnamese", "marks": [{"type": "link", "attrs": {"href": "/blog/common-vietnamese-mistakes"}}]}, {"type": "text", "text": ", or "}, {"type": "text", "text": "find a Vietnamese partner", "marks": [{"type": "link", "attrs": {"href": "/languages/vietnamese"}}]}, {"type": "text", "text": " and try your first "}, {"type": "text", "text": "Chào anh", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " or "}, {"type": "text", "text": "Chào chị", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": "."}]}]}$j$::jsonb, 4, now() - interval '1 minutes', now() - interval '1 minutes', now() - interval '1 minutes', now() - interval '1 minutes') on conflict (slug) do nothing;

insert into public.blog_posts (slug, draft, is_live, title, seo_title, description, kicker, summary, body, read_minutes, published_at, updated_at, created_at, draft_saved_at) values (
  'common-vietnamese-mistakes', $j${"title": "Common Vietnamese Mistakes English Speakers Make (and How to Fix Them)", "seo_title": "Common Vietnamese Mistakes and Fixes", "description": "Nine Vietnamese mistakes English speakers often make, each with the corrected sentence and the rule behind it, from là and word order to classifiers.", "kicker": "Learning Vietnamese", "summary": "Most Vietnamese mistakes made by English speakers come from translating English word by word. Below are nine common ones, each with the fix and the reason. Learn the patterns behind them and you will correct many other sentences too.", "cover_url": null, "cover_alt": null, "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Adding là before an adjective"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi là đói.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tôi đói.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (I am hungry.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "English needs \"am\", so learners reach for "}, {"type": "text", "text": "là", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ". In Vietnamese, words like \"hungry\" work like verbs and take no \"to be\". "}, {"type": "text", "text": "Là", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " joins two nouns, as in "}, {"type": "text", "text": "Tôi là sinh viên", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"I am a student\")."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Using không là for \"am not\""}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi không là sinh viên.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tôi không phải là sinh viên.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (I am not a student.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "To say something is not something else, use "}, {"type": "text", "text": "không phải là", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ". With adjectives, you only need "}, {"type": "text", "text": "không", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": "}, {"type": "text", "text": "Tôi không đói", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"I am not hungry\")."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Putting the describing word first"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi thích ngon cà phê.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tôi thích cà phê ngon.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (I like good coffee.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "English puts the adjective first. Vietnamese puts the thing first and the description after it. Think of it as \"coffee good\"."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Forgetting the classifier"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi có một mèo.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tôi có một con mèo.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (I have a cat.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When you count things in Vietnamese, a classifier usually goes between the number and the noun. "}, {"type": "text", "text": "Con", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " is used for animals, among other things, while "}, {"type": "text", "text": "quyển", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " or "}, {"type": "text", "text": "cuốn", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " is used for books: "}, {"type": "text", "text": "hai quyển sách", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"two books\"). If you aren't sure which one to use, learn each noun together with its classifier from the start."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Putting \"very\" in the wrong place"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cô ấy đẹp rất.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Cô ấy rất đẹp.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (She is very beautiful.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Rất", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " goes before the adjective. The confusing part is that "}, {"type": "text", "text": "quá", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " usually goes after it, and it is common in everyday speech: "}, {"type": "text", "text": "đẹp quá", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"so beautiful\"). Learn them as two separate patterns."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Getting possession backwards"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tôi mẹ", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "mẹ tôi", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (my mother)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The owned thing comes first in Vietnamese. You can also add "}, {"type": "text", "text": "của", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ", meaning \"of\": "}, {"type": "text", "text": "sách của tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"my book\", or literally \"book of me\")."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Asking questions with only a question mark"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bạn đói?", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bạn có đói không?", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (Are you hungry?)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Raising your voice or adding a question mark can show surprise, but the usual yes-or-no pattern puts "}, {"type": "text", "text": "có", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " before the word and "}, {"type": "text", "text": "không", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " at the end. For nouns, use "}, {"type": "text", "text": "có phải là ... không", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": "}, {"type": "text", "text": "Bạn có phải là sinh viên không?", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"Are you a student?\")."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "8. Leaving out tone marks and accents"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Toi doi.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tôi đói.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (I am hungry.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tone marks and accents are not decoration: they are part of the word. Without them, "}, {"type": "text", "text": "doi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " could be read as "}, {"type": "text", "text": "đói", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"hungry\"), "}, {"type": "text", "text": "đợi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"to wait\"), "}, {"type": "text", "text": "đôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"a pair\") or "}, {"type": "text", "text": "đồi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"a hill\"). Friends may guess your meaning from context, but it slows them down, and it is a serious problem in formal writing. Set up a Vietnamese keyboard early, so that typing the marks becomes a habit."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "9. Saying tôi to everyone"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi cảm ơn chị.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Em cảm ơn chị ạ.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (Thank you, said to an older woman.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The grammar is correct, but it can sound cold. Vietnamese speakers usually pick words for \"I\" and \"you\" that reflect age and relationship. We cover this fully in "}, {"type": "text", "text": "Vietnamese pronouns explained", "marks": [{"type": "link", "attrs": {"href": "/blog/vietnamese-pronouns-explained"}}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why these mistakes can last for years"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Mistakes like these rarely get in the way of being understood. Your friends know what "}, {"type": "text", "text": "Tôi là đói", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " means, so they let it pass. Unless someone stops you, the wrong version can become a habit. That's why learners can reach a good level and still make beginner mistakes, and why you should "}, {"type": "text", "text": "ask native speakers to correct you", "marks": [{"type": "link", "attrs": {"href": "/blog/corrections-from-native-speakers"}}]}, {"type": "text", "text": " even when they understood you."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Turn your mistakes into a personal list"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Reading other people's mistakes helps a little. Seeing your own helps a lot more, because you wrote the sentence and you know what you were trying to say. On "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", a native speaker can edit your message where you wrote it. You see the changes in red and green, and when you accept a correction it goes into your phrasebook. After a few weeks, you will have a list of the exact errors you personally tend to make."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Practise Vietnamese with native speakers", "marks": [{"type": "link", "attrs": {"href": "/languages/vietnamese"}}]}, {"type": "text", "text": " for free, and get your next sentence checked."}]}]}}$j$::jsonb, true,
  $t$Common Vietnamese Mistakes English Speakers Make (and How to Fix Them)$t$, $t$Common Vietnamese Mistakes and Fixes$t$, $t$Nine Vietnamese mistakes English speakers often make, each with the corrected sentence and the rule behind it, from là and word order to classifiers.$t$, $t$Learning Vietnamese$t$, $t$Most Vietnamese mistakes made by English speakers come from translating English word by word. Below are nine common ones, each with the fix and the reason. Learn the patterns behind them and you will correct many other sentences too.$t$,
  $j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Adding là before an adjective"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi là đói.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tôi đói.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (I am hungry.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "English needs \"am\", so learners reach for "}, {"type": "text", "text": "là", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ". In Vietnamese, words like \"hungry\" work like verbs and take no \"to be\". "}, {"type": "text", "text": "Là", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " joins two nouns, as in "}, {"type": "text", "text": "Tôi là sinh viên", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"I am a student\")."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Using không là for \"am not\""}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi không là sinh viên.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tôi không phải là sinh viên.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (I am not a student.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "To say something is not something else, use "}, {"type": "text", "text": "không phải là", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ". With adjectives, you only need "}, {"type": "text", "text": "không", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": "}, {"type": "text", "text": "Tôi không đói", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"I am not hungry\")."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Putting the describing word first"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi thích ngon cà phê.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tôi thích cà phê ngon.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (I like good coffee.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "English puts the adjective first. Vietnamese puts the thing first and the description after it. Think of it as \"coffee good\"."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Forgetting the classifier"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi có một mèo.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tôi có một con mèo.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (I have a cat.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When you count things in Vietnamese, a classifier usually goes between the number and the noun. "}, {"type": "text", "text": "Con", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " is used for animals, among other things, while "}, {"type": "text", "text": "quyển", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " or "}, {"type": "text", "text": "cuốn", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " is used for books: "}, {"type": "text", "text": "hai quyển sách", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"two books\"). If you aren't sure which one to use, learn each noun together with its classifier from the start."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Putting \"very\" in the wrong place"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cô ấy đẹp rất.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Cô ấy rất đẹp.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (She is very beautiful.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Rất", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " goes before the adjective. The confusing part is that "}, {"type": "text", "text": "quá", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " usually goes after it, and it is common in everyday speech: "}, {"type": "text", "text": "đẹp quá", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"so beautiful\"). Learn them as two separate patterns."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Getting possession backwards"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tôi mẹ", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "mẹ tôi", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (my mother)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The owned thing comes first in Vietnamese. You can also add "}, {"type": "text", "text": "của", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ", meaning \"of\": "}, {"type": "text", "text": "sách của tôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"my book\", or literally \"book of me\")."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Asking questions with only a question mark"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bạn đói?", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bạn có đói không?", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (Are you hungry?)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Raising your voice or adding a question mark can show surprise, but the usual yes-or-no pattern puts "}, {"type": "text", "text": "có", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " before the word and "}, {"type": "text", "text": "không", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " at the end. For nouns, use "}, {"type": "text", "text": "có phải là ... không", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ": "}, {"type": "text", "text": "Bạn có phải là sinh viên không?", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"Are you a student?\")."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "8. Leaving out tone marks and accents"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Toi doi.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tôi đói.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (I am hungry.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tone marks and accents are not decoration: they are part of the word. Without them, "}, {"type": "text", "text": "doi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " could be read as "}, {"type": "text", "text": "đói", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"hungry\"), "}, {"type": "text", "text": "đợi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"to wait\"), "}, {"type": "text", "text": "đôi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"a pair\") or "}, {"type": "text", "text": "đồi", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"a hill\"). Friends may guess your meaning from context, but it slows them down, and it is a serious problem in formal writing. Set up a Vietnamese keyboard early, so that typing the marks becomes a habit."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "9. Saying tôi to everyone"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tôi cảm ơn chị.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Em cảm ơn chị ạ.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (Thank you, said to an older woman.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The grammar is correct, but it can sound cold. Vietnamese speakers usually pick words for \"I\" and \"you\" that reflect age and relationship. We cover this fully in "}, {"type": "text", "text": "Vietnamese pronouns explained", "marks": [{"type": "link", "attrs": {"href": "/blog/vietnamese-pronouns-explained"}}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why these mistakes can last for years"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Mistakes like these rarely get in the way of being understood. Your friends know what "}, {"type": "text", "text": "Tôi là đói", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " means, so they let it pass. Unless someone stops you, the wrong version can become a habit. That's why learners can reach a good level and still make beginner mistakes, and why you should "}, {"type": "text", "text": "ask native speakers to correct you", "marks": [{"type": "link", "attrs": {"href": "/blog/corrections-from-native-speakers"}}]}, {"type": "text", "text": " even when they understood you."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Turn your mistakes into a personal list"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Reading other people's mistakes helps a little. Seeing your own helps a lot more, because you wrote the sentence and you know what you were trying to say. On "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", a native speaker can edit your message where you wrote it. You see the changes in red and green, and when you accept a correction it goes into your phrasebook. After a few weeks, you will have a list of the exact errors you personally tend to make."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Practise Vietnamese with native speakers", "marks": [{"type": "link", "attrs": {"href": "/languages/vietnamese"}}]}, {"type": "text", "text": " for free, and get your next sentence checked."}]}]}$j$::jsonb, 4, now() - interval '2 minutes', now() - interval '2 minutes', now() - interval '2 minutes', now() - interval '2 minutes') on conflict (slug) do nothing;

insert into public.blog_posts (slug, draft, is_live, title, seo_title, description, kicker, summary, body, read_minutes, published_at, updated_at, created_at, draft_saved_at) values (
  'how-to-learn-swahili-online', $j${"title": "How to Learn Swahili Online: A Beginner's Guide for English Speakers", "seo_title": "How to Learn Swahili Online", "description": "A clear beginner's guide to learning Swahili online: greetings, why spelling is easy, noun classes, how verbs are built, and how to get real practice.", "kicker": "Learning Swahili", "summary": "Swahili is a friendly language to start with: it is written in the Latin alphabet, is spelled much as it sounds and has no tones. The main new idea is noun classes, which change the beginning of words. Start with greetings, learn how verbs are built, and use the language with real people as early as you can.", "cover_url": null, "cover_alt": null, "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why Swahili is a good language to start"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Swahili is spoken in Kenya, Tanzania, Uganda and across East and Central Africa, so it can open up a large part of the continent. For English speakers, it has some real advantages:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Familiar letters.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " It uses the Latin alphabet, so you can read words from your first day."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Regular spelling.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Words are mostly spelled the way they sound."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Predictable stress.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " The stress usually falls on the second-to-last syllable."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "No tones.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Unlike Vietnamese or Chinese, you do not need to learn tones."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Start with greetings"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Greetings matter in East Africa, and people often take a moment over them before getting to the point. Learn these first:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Habari?", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = How are you? (literally \"news?\")"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nzuri.", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = Good. A common reply."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hujambo?", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "Sijambo.", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = How are you? and I'm fine."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Asante.", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = Thank you."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Karibu.", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = Welcome, or you're welcome."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tafadhali.", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = Please."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You may know "}, {"type": "text", "text": "Jambo", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " from travel guides. People will understand it, but it is often heard as a greeting for tourists. Using "}, {"type": "text", "text": "Habari", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " or "}, {"type": "text", "text": "Hujambo", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " shows you have gone a little further."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "To greet someone older with respect, some speakers use "}, {"type": "text", "text": "Shikamoo", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ". The reply is "}, {"type": "text", "text": "Marahaba", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ". It's a lovely one to know, especially in Tanzania."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Noun classes: the big new idea"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Swahili sorts nouns into classes, each with its own prefix. English speakers often find this strange at first, but the patterns are visible right there in the words:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "mtu", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " (person) becomes "}, {"type": "text", "text": "watu", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " (people)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "kitabu", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " (book) becomes "}, {"type": "text", "text": "vitabu", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " (books)"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The prefix also spreads to other words in the sentence, including adjectives. The word for \"good\" changes to match the noun:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "mtu mzuri", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ": a good person"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "watu wazuri", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ": good people"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "kitabu kizuri", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ": a good book"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "vitabu vizuri", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ": good books"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Don't try to memorise a chart of every class at the start. Learn the "}, {"type": "text", "text": "m-/wa-", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "ki-/vi-", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " patterns, and pick up the others by seeing them in use."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Verbs are built like blocks"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Swahili verbs are built from small parts, so one word can say what English needs several words for. Take "}, {"type": "text", "text": "soma", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ", meaning read or study:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ninasoma", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ": I am reading. ("}, {"type": "text", "text": "ni", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = I, "}, {"type": "text", "text": "na", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = present, "}, {"type": "text", "text": "soma", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = read)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nilisoma", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ": I read, in the past. ("}, {"type": "text", "text": "li", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = past)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nitasoma", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ": I will read. ("}, {"type": "text", "text": "ta", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = future)"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Once you know this pattern, you can use it with every new verb you learn. It's one of the most satisfying parts of the language."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "A mistake to expect"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A beginner might use the word for \"good\" without changing its prefix:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "kitabu nzuri", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "sw"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "kitabu kizuri", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " (a good book)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Another common mistake is using a pronoun and a bare verb, the way you would in English:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Mimi soma.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "sw"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ninasoma.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " (I am reading.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "People will usually understand you either way. That's why you need someone who is willing to correct you."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "A simple study routine"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Learn a little every day.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Twenty minutes each day works better than one long session a week."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Learn sentences, not single words.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " "}, {"type": "text", "text": "Ninapenda kahawa", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " (\"I like coffee\") teaches you a verb, its prefix and a useful sentence."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Listen as well.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Find Swahili music, radio or videos, because this guide can't teach you how the language sounds."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Write something to a real person early.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Even \""}, {"type": "text", "text": "Habari? Ninasoma Kiswahili.", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": "\" (\"How are you? I'm studying Swahili.\") is a real start."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Find someone to practise with"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Swahili learners often have fewer resources than people learning Spanish or French, which makes native speakers even more valuable. On "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", you can "}, {"type": "text", "text": "practise Swahili in text chat", "marks": [{"type": "link", "attrs": {"href": "/languages/swahili"}}]}, {"type": "text", "text": " for free. When a native speaker corrects your sentence, you see exactly what changed, and the phrase is saved to your phrasebook once you accept it. There are no tutors or lessons here: it's people helping people."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "New to this kind of practice? Read "}, {"type": "text", "text": "what a language exchange is", "marks": [{"type": "link", "attrs": {"href": "/blog/what-is-a-language-exchange"}}]}, {"type": "text", "text": ", or "}, {"type": "text", "text": "create a free account", "marks": [{"type": "link", "attrs": {"href": "/signup"}}]}, {"type": "text", "text": " and send your first "}, {"type": "text", "text": "Habari?", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " today."}]}]}}$j$::jsonb, true,
  $t$How to Learn Swahili Online: A Beginner's Guide for English Speakers$t$, $t$How to Learn Swahili Online$t$, $t$A clear beginner's guide to learning Swahili online: greetings, why spelling is easy, noun classes, how verbs are built, and how to get real practice.$t$, $t$Learning Swahili$t$, $t$Swahili is a friendly language to start with: it is written in the Latin alphabet, is spelled much as it sounds and has no tones. The main new idea is noun classes, which change the beginning of words. Start with greetings, learn how verbs are built, and use the language with real people as early as you can.$t$,
