g": "sw"}}]}, {"type": "text", "text": ": a good book"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "vitabu vizuri", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ": good books"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Don't try to memorise a chart of every class at the start. Learn the "}, {"type": "text", "text": "m-/wa-", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "ki-/vi-", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " patterns, and pick up the others by seeing them in use."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Verbs are built like blocks"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Swahili verbs are built from small parts, so one word can say what English needs several words for. Take "}, {"type": "text", "text": "soma", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ", meaning read or study:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ninasoma", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ": I am reading. ("}, {"type": "text", "text": "ni", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = I, "}, {"type": "text", "text": "na", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = present, "}, {"type": "text", "text": "soma", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = read)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nilisoma", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ": I read, in the past. ("}, {"type": "text", "text": "li", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = past)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nitasoma", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": ": I will read. ("}, {"type": "text", "text": "ta", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " = future)"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Once you know this pattern, you can use it with every new verb you learn. It's one of the most satisfying parts of the language."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "A mistake to expect"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A beginner might use the word for \"good\" without changing its prefix:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "kitabu nzuri", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "sw"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "kitabu kizuri", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " (a good book)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Another common mistake is using a pronoun and a bare verb, the way you would in English:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Mimi soma.", "marks": [{"type": "strike"}, {"type": "lang", "attrs": {"lang": "sw"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ninasoma.", "marks": [{"type": "bold"}, {"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " (I am reading.)"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "People will usually understand you either way. That's why you need someone who is willing to correct you."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "A simple study routine"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Learn a little every day.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Twenty minutes each day works better than one long session a week."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Learn sentences, not single words.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " "}, {"type": "text", "text": "Ninapenda kahawa", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " (\"I like coffee\") teaches you a verb, its prefix and a useful sentence."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Listen as well.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Find Swahili music, radio or videos, because this guide can't teach you how the language sounds."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Write something to a real person early.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Even \""}, {"type": "text", "text": "Habari? Ninasoma Kiswahili.", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": "\" (\"How are you? I'm studying Swahili.\") is a real start."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Find someone to practise with"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Swahili learners often have fewer resources than people learning Spanish or French, which makes native speakers even more valuable. On "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", you can "}, {"type": "text", "text": "practise Swahili in text chat", "marks": [{"type": "link", "attrs": {"href": "/languages/swahili"}}]}, {"type": "text", "text": " for free. When a native speaker corrects your sentence, you see exactly what changed, and the phrase is saved to your phrasebook once you accept it. There are no tutors or lessons here: it's people helping people."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "New to this kind of practice? Read "}, {"type": "text", "text": "what a language exchange is", "marks": [{"type": "link", "attrs": {"href": "/blog/what-is-a-language-exchange"}}]}, {"type": "text", "text": ", or "}, {"type": "text", "text": "create a free account", "marks": [{"type": "link", "attrs": {"href": "/signup"}}]}, {"type": "text", "text": " and send your first "}, {"type": "text", "text": "Habari?", "marks": [{"type": "lang", "attrs": {"lang": "sw"}}]}, {"type": "text", "text": " today."}]}]}$j$::jsonb, 4, now() - interval '3 minutes', now() - interval '3 minutes', now() - interval '3 minutes', now() - interval '3 minutes') on conflict (slug) do nothing;

insert into public.blog_posts (slug, draft, is_live, title, seo_title, description, kicker, summary, body, read_minutes, published_at, updated_at, created_at, draft_saved_at) values (
  'help-someone-learn-your-language', $j${"title": "How to Help Someone Learn Your Language (No Teaching Degree Needed)", "seo_title": "How to Help Someone Learn Your Language", "description": "You don't need to be a teacher to help a learner. What native speakers can do in a chat, what to do when you can't explain a rule, and how to keep it fun.", "kicker": "For native speakers", "summary": "You don't need to know grammar terms or have any teaching experience to help someone learn your language. You already know how it should sound. Showing the natural version of a sentence, patiently and consistently, is one of the most useful things a learner can get.", "cover_url": null, "cover_alt": null, "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "You know more than you think"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Many native speakers say \"I couldn't teach my language. I don't even know the rules.\" But a learner mainly needs something that textbooks can't give: a person who instantly knows when a sentence sounds odd."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A teacher plans lessons and explains systems. A language partner only has to do three simple things: talk, show a better way to say something, and be kind while doing it. That's a job you can do without any training."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "You've been on the other side"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Linh is a native Vietnamese speaker who is learning English. Linh often writes \"I hungry\", because the Vietnamese sentence "}, {"type": "text", "text": "Tôi đói", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " has no word for \"am\". Meanwhile, Tom, who speaks English and is learning Vietnamese, writes "}, {"type": "text", "text": "Tôi là đói", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ", because English does need one."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Each of them is making the mirror image of the other's mistake, and each can fix the other's in seconds. Neither needs a teaching degree. If you've ever learned another language, you know how much it means when someone takes the time to help you."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Five things that help a learner most"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Give the natural version.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " \"We'd say it like this\" is often all a learner needs."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fix one or two things at a time.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Don't correct every word in a long message. Choose what matters most, as too many changes can be discouraging."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ask about what they're learning.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Find out what they want from the language: exams, work or travel. Then use words that fit that goal."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Use simple language.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Write shorter sentences than usual, and avoid slang unless you explain it."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Reply to the message, too.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A learner wrote to you to communicate. Respond to what they said as well as how they said it."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "When you can't explain the rule"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Learners sometimes ask \"why?\", and often you won't know. That's fine. These are honest answers, and they still help:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "I can't explain the rule, but this is how everyone says it."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Both are correct, but the second one sounds more natural."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Let me give you two more examples so you can see the pattern."}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Examples often teach better than rules anyway. If you do want an explanation, the learner can look it up, and you may both learn something. Please don't make up a rule just to have an answer."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Being clear about what kind of help you offer"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can set limits, and you probably should. It's fine to say you can only chat in the evenings, that you won't check long essays, or that you'd like to keep the conversation in one language for a while. You're a volunteer, not a service. Learners tend to respect a partner who is clear about this, and it stops helping from becoming a chore."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why people enjoy doing it"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Helping is not only about being generous. People often say they see their own language in a new way. You discover how strange some of your own idioms are, and you learn about the life of someone in another country. If you're learning a language yourself, it's also a reminder that mistakes are normal."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How helping works on The Fluency Talks"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "On "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", you can help in several ways if you're a native speaker of a language, or a learner verified at B1 or above in it:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Correct messages in chat.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Edit a sentence right where it was written and add a note if you like. The learner sees what changed and chooses whether to accept it."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Earn points.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Each correction someone accepts earns you 5 points, up to 10 rewarded corrections a day and 3 from the same learner."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Answer bounties.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " When a learner gets stuck, they can spend 50 points to ask a question. If they accept your answer, you receive those points."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Post to the community library.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Share phrases, idioms and grammar tips for other members to read and save."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "It's all free, and you don't need to be learning anything yourself to take part. Before you begin, read "}, {"type": "text", "text": "how to correct someone's grammar without being rude", "marks": [{"type": "link", "attrs": {"href": "/blog/how-to-correct-grammar-politely"}}]}, {"type": "text", "text": "."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Do you speak a language others want to learn? "}, {"type": "text", "text": "See the languages people are practising", "marks": [{"type": "link", "attrs": {"href": "/languages"}}]}, {"type": "text", "text": ", then "}, {"type": "text", "text": "join for free", "marks": [{"type": "link", "attrs": {"href": "/signup"}}]}, {"type": "text", "text": " and help someone a few steps behind you."}]}]}}$j$::jsonb, true,
  $t$How to Help Someone Learn Your Language (No Teaching Degree Needed)$t$, $t$How to Help Someone Learn Your Language$t$, $t$You don't need to be a teacher to help a learner. What native speakers can do in a chat, what to do when you can't explain a rule, and how to keep it fun.$t$, $t$For native speakers$t$, $t$You don't need to know grammar terms or have any teaching experience to help someone learn your language. You already know how it should sound. Showing the natural version of a sentence, patiently and consistently, is one of the most useful things a learner can get.$t$,
  $j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "You know more than you think"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Many native speakers say \"I couldn't teach my language. I don't even know the rules.\" But a learner mainly needs something that textbooks can't give: a person who instantly knows when a sentence sounds odd."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A teacher plans lessons and explains systems. A language partner only has to do three simple things: talk, show a better way to say something, and be kind while doing it. That's a job you can do without any training."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "You've been on the other side"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Linh is a native Vietnamese speaker who is learning English. Linh often writes \"I hungry\", because the Vietnamese sentence "}, {"type": "text", "text": "Tôi đói", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " has no word for \"am\". Meanwhile, Tom, who speaks English and is learning Vietnamese, writes "}, {"type": "text", "text": "Tôi là đói", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ", because English does need one."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Each of them is making the mirror image of the other's mistake, and each can fix the other's in seconds. Neither needs a teaching degree. If you've ever learned another language, you know how much it means when someone takes the time to help you."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Five things that help a learner most"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Give the natural version.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " \"We'd say it like this\" is often all a learner needs."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fix one or two things at a time.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Don't correct every word in a long message. Choose what matters most, as too many changes can be discouraging."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ask about what they're learning.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Find out what they want from the language: exams, work or travel. Then use words that fit that goal."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Use simple language.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Write shorter sentences than usual, and avoid slang unless you explain it."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Reply to the message, too.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A learner wrote to you to communicate. Respond to what they said as well as how they said it."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "When you can't explain the rule"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Learners sometimes ask \"why?\", and often you won't know. That's fine. These are honest answers, and they still help:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "I can't explain the rule, but this is how everyone says it."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Both are correct, but the second one sounds more natural."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Let me give you two more examples so you can see the pattern."}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Examples often teach better than rules anyway. If you do want an explanation, the learner can look it up, and you may both learn something. Please don't make up a rule just to have an answer."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Being clear about what kind of help you offer"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can set limits, and you probably should. It's fine to say you can only chat in the evenings, that you won't check long essays, or that you'd like to keep the conversation in one language for a while. You're a volunteer, not a service. Learners tend to respect a partner who is clear about this, and it stops helping from becoming a chore."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why people enjoy doing it"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Helping is not only about being generous. People often say they see their own language in a new way. You discover how strange some of your own idioms are, and you learn about the life of someone in another country. If you're learning a language yourself, it's also a reminder that mistakes are normal."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How helping works on The Fluency Talks"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "On "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", you can help in several ways if you're a native speaker of a language, or a learner verified at B1 or above in it:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Correct messages in chat.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Edit a sentence right where it was written and add a note if you like. The learner sees what changed and chooses whether to accept it."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Earn points.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Each correction someone accepts earns you 5 points, up to 10 rewarded corrections a day and 3 from the same learner."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Answer bounties.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " When a learner gets stuck, they can spend 50 points to ask a question. If they accept your answer, you receive those points."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Post to the community library.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Share phrases, idioms and grammar tips for other members to read and save."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "It's all free, and you don't need to be learning anything yourself to take part. Before you begin, read "}, {"type": "text", "text": "how to correct someone's grammar without being rude", "marks": [{"type": "link", "attrs": {"href": "/blog/how-to-correct-grammar-politely"}}]}, {"type": "text", "text": "."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Do you speak a language others want to learn? "}, {"type": "text", "text": "See the languages people are practising", "marks": [{"type": "link", "attrs": {"href": "/languages"}}]}, {"type": "text", "text": ", then "}, {"type": "text", "text": "join for free", "marks": [{"type": "link", "attrs": {"href": "/signup"}}]}, {"type": "text", "text": " and help someone a few steps behind you."}]}]}$j$::jsonb, 4, now() - interval '4 minutes', now() - interval '4 minutes', now() - interval '4 minutes', now() - interval '4 minutes') on conflict (slug) do nothing;

insert into public.blog_posts (slug, draft, is_live, title, seo_title, description, kicker, summary, body, read_minutes, published_at, updated_at, created_at, draft_saved_at) values (
  'how-to-correct-grammar-politely', $j${"title": "How to Correct Someone's Grammar Without Being Rude", "seo_title": "How to Correct Someone's Grammar Politely", "description": "How to correct someone's grammar politely, with phrases you can copy, what to do about timing and tone, and when it's better to say nothing at all.", "kicker": "For native speakers", "summary": "A polite correction starts with permission, answers the person's message first and shows the better version without any judgement. If someone hasn't asked to be corrected, it is usually better to leave their grammar alone. The phrases below will help you be useful without sounding superior.", "cover_url": null, "cover_alt": null, "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "First rule: only correct people who want it"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Correcting a stranger's grammar in a comment thread, or a colleague in a meeting, is rarely welcome. They're trying to communicate with you, not take a test. The advice in this article is for situations where someone is learning and has asked for feedback, such as with a language partner."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you aren't sure, ask:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Would you like me to correct your English when I notice something, or would you rather just chat?"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Some people want every error fixed. Others only want help when they get stuck. Asking saves you both from awkward moments."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Answer first, correct second"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A person who writes \"Yesterday I go to the beach with my family!\" is telling you about their day. If your only reply is \"went, not go\", they may feel like they've handed in homework. Respond as a person first:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "That sounds lovely! Which beach did you go to? Small fix: \"Yesterday I went to the beach\"."}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Notice that the first part already uses \"went\" in a natural way. This is often enough on its own for small slips, as people learn a lot from simply seeing the right form."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Phrases that sound friendly"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Words like \"wrong\" and \"should\" can make a correction sound like a judgement. Try these alternatives:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"We'd usually say...\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"A more natural way to say this is...\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"This is clear, and here's how a native speaker might put it...\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Small thing:...\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"I understood you perfectly. One tip:...\""}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The same correction can feel very different depending on how you say it:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "No, that's wrong. It's \"I agree\", not \"I am agree\".", "marks": [{"type": "strike"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "We'd just say \"I agree\". \"Agree\" is already a verb, so it doesn't need \"am\".", "marks": [{"type": "bold"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Explain only as much as they need"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A beginner usually needs the right version and little else. An advanced learner often wants to know why two options feel different. If you can give a short reason, like the one above, it helps them avoid the same mistake in future. If you can't, it's fine to just say \"that's how we say it\". Avoid long grammar lessons unless they ask."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Choose your battles"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You don't need to correct everything. Before you correct, ask yourself:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Did it change the meaning?", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Fix this first. These errors can cause real misunderstandings."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Does it keep happening?", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A repeated mistake is worth pointing out once, gently."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Is it what they asked about?", "marks": [{"type": "bold"}]}, {"type": "text", "text": " If they're preparing for an exam, grammar may matter. If they're practising small talk, it may not."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "How much have I corrected already?", "marks": [{"type": "bold"}]}, {"type": "text", "text": " One or two fixes per message is plenty for most people."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Mistakes to avoid"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Don't laugh at errors,", "marks": [{"type": "bold"}]}, {"type": "text", "text": " even funny ones, unless the other person laughs first."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Don't correct regional or informal usage as if it were wrong.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " \"That's how people say it where I'm from\" is often true for both of you."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Don't guess.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " If you aren't sure, say so. A confident but wrong correction does more harm than none."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Don't correct in front of others", "marks": [{"type": "bold"}]}, {"type": "text", "text": " if you can do it privately."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Don't take it personally", "marks": [{"type": "bold"}]}, {"type": "text", "text": " if they keep their own wording. It's their sentence, and they get to decide."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to accept a \"thank you\""}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When a learner thanks you, reply warmly and mention something they did well, like \"Your English is improving so quickly\" if it's true. Honest encouragement makes people keep writing, and that's how they will really improve."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How The Fluency Talks makes this easier"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": " is designed around this kind of correction. Instead of quoting someone's mistake in a separate message, you edit their sentence right where they wrote it and can add a short note. They see the changes in red and green, and they decide whether to accept. Your conversation keeps flowing, and the decision remains in their hands."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Learners can also rate whether a correction was helpful, which is a nice incentive to be kind and clear. Accepted corrections earn you 5 points and go into the learner's phrasebook."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you're on the receiving end, read "}, {"type": "text", "text": "how to get corrections from native speakers", "marks": [{"type": "link", "attrs": {"href": "/blog/corrections-from-native-speakers"}}]}, {"type": "text", "text": ". If you're ready to help, here's more on "}, {"type": "text", "text": "how to help someone learn your language", "marks": [{"type": "link", "attrs": {"href": "/blog/help-someone-learn-your-language"}}]}, {"type": "text", "text": "."}]}]}}$j$::jsonb, true,
  $t$How to Correct Someone's Grammar Without Being Rude$t$, $t$How to Correct Someone's Grammar Politely$t$, $t$How to correct someone's grammar politely, with phrases you can copy, what to do about timing and tone, and when it's better to say nothing at all.$t$, $t$For native speakers$t$, $t$A polite correction starts with permission, answers the person's message first and shows the better version without any judgement. If someone hasn't asked to be corrected, it is usually better to leave their grammar alone. The phrases below will help you be useful without sounding superior.$t$,
