tent": [{"type": "text", "text": "You don't need to correct everything. Before you correct, ask yourself:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Did it change the meaning?", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Fix this first. These errors can cause real misunderstandings."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Does it keep happening?", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A repeated mistake is worth pointing out once, gently."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Is it what they asked about?", "marks": [{"type": "bold"}]}, {"type": "text", "text": " If they're preparing for an exam, grammar may matter. If they're practising small talk, it may not."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "How much have I corrected already?", "marks": [{"type": "bold"}]}, {"type": "text", "text": " One or two fixes per message is plenty for most people."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Mistakes to avoid"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Don't laugh at errors,", "marks": [{"type": "bold"}]}, {"type": "text", "text": " even funny ones, unless the other person laughs first."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Don't correct regional or informal usage as if it were wrong.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " \"That's how people say it where I'm from\" is often true for both of you."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Don't guess.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " If you aren't sure, say so. A confident but wrong correction does more harm than none."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Don't correct in front of others", "marks": [{"type": "bold"}]}, {"type": "text", "text": " if you can do it privately."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Don't take it personally", "marks": [{"type": "bold"}]}, {"type": "text", "text": " if they keep their own wording. It's their sentence, and they get to decide."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to accept a \"thank you\""}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When a learner thanks you, reply warmly and mention something they did well, like \"Your English is improving so quickly\" if it's true. Honest encouragement makes people keep writing, and that's how they will really improve."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How The Fluency Talks makes this easier"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": " is designed around this kind of correction. Instead of quoting someone's mistake in a separate message, you edit their sentence right where they wrote it and can add a short note. They see the changes in red and green, and they decide whether to accept. Your conversation keeps flowing, and the decision remains in their hands."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Learners can also rate whether a correction was helpful, which is a nice incentive to be kind and clear. Accepted corrections earn you 5 points and go into the learner's phrasebook."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you're on the receiving end, read "}, {"type": "text", "text": "how to get corrections from native speakers", "marks": [{"type": "link", "attrs": {"href": "/blog/corrections-from-native-speakers"}}]}, {"type": "text", "text": ". If you're ready to help, here's more on "}, {"type": "text", "text": "how to help someone learn your language", "marks": [{"type": "link", "attrs": {"href": "/blog/help-someone-learn-your-language"}}]}, {"type": "text", "text": "."}]}]}$j$::jsonb, 4, now() - interval '5 minutes', now() - interval '5 minutes', now() - interval '5 minutes', now() - interval '5 minutes') on conflict (slug) do nothing;

insert into public.blog_posts (slug, draft, is_live, title, seo_title, description, kicker, summary, body, read_minutes, published_at, updated_at, created_at, draft_saved_at) values (
  'cefr-levels-explained', $j${"title": "CEFR Levels A1 to C2 Explained: What You Can Actually Do at Each Level", "seo_title": "CEFR Levels A1 to C2 Explained", "description": "What A1, A2, B1, B2, C1 and C2 really mean, with everyday examples for each level, how to work out your own, and how to keep moving up.", "kicker": "Language levels", "summary": "The CEFR describes language ability on six levels, from A1 for beginners to C2 for near-native users. Each level is defined by what you can do with the language, not by how many words you know. Most learners find it most useful as a way to choose their next goal.", "cover_url": null, "cover_alt": null, "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What the CEFR is"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "CEFR stands for the Common European Framework of Reference for Languages. It was published by the Council of Europe and is now used around the world, for many languages, by schools, employers and exam boards. It has three bands, A (basic), B (independent) and C (proficient), and each band is split in two."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The six levels, in everyday terms"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "A1: Beginner"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can introduce yourself, ask very simple questions and use common everyday phrases, if the other person speaks slowly and is willing to help. For example: \"My name is Tom. I am from Canada. I would like a coffee.\""}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "A2: Elementary"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can handle simple, routine tasks, such as shopping, asking for directions and talking about your family or job. You can write a short, simple message, though you often need to think before you say something."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "B1: Intermediate"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can get by in most situations while travelling. You can talk about your experiences, explain your plans and give simple reasons for your opinions. Many learners feel this is the point where the language starts to feel usable, and mistakes rarely stop people understanding you on familiar topics."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "B2: Upper intermediate"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can talk with native speakers fairly easily, without a lot of strain on either side. You can follow the main ideas of complex texts, argue for your point of view and work on topics in your own field. Many universities and employers look for roughly this level, but requirements vary, so check before you apply."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "C1: Advanced"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You express yourself fluently without much obvious searching for words. You can use the language flexibly for work and study, understand long and demanding texts, and write clear, well-structured documents."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "C2: Near-native"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can understand almost everything you hear or read with ease. You can summarise information from different sources and express fine shades of meaning. Most learners never need this level, and many native speakers wouldn't find a C2 exam easy."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why B1 feels so hard"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Learners often talk about the \"intermediate plateau\". In the beginning, every new word makes a visible difference. Moving from B1 to B2 takes more time, since you are now refining what you say rather than simply learning how to say it. Your progress hasn't stopped: it has just become harder to see. Regular correction helps at this stage, because you may no longer notice the errors that remain."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to work out your own level"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Read the descriptions honestly.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Pick the level where you can do almost everything comfortably, not the one you sometimes reach on a good day."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Try a free online placement test.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Use it as a rough guide, as many only test grammar and vocabulary."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Take an official exam if you need proof.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Employers and universities usually want a recognised certificate, and the exam differs from one language to another."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Remember that your skills can differ.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " It's common to read at B2 and write at A2. Our guide to "}, {"type": "text", "text": "university study in Vietnamese", "marks": [{"type": "link", "attrs": {"href": "/blog/studying-at-university-in-vietnam"}}]}, {"type": "text", "text": " shows how much this can matter."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to move up a level"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Whatever your current level, there are a few things that help:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A1 to A2:", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Learn useful sentences, and start writing short messages as soon as you can."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A2 to B1:", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Talk about your own life. Practise using past and future forms in real conversations."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "B1 to B2:", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Ask to have natural phrasing corrected, not only grammar. Read about things you already care about."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "B2 to C1:", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Work on precision. Learn the formal language of your field, and notice how native speakers structure an argument."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How levels work on The Fluency Talks"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When you join "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", you pick your level from A1 to C2 as a starting point. A separate verified level is then earned through your activity: how much you write, on how many days, whether native speakers reply to you, and how often your messages need correcting. At higher levels, the corrections you give others count too."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Once you're verified at B1 or above, you can correct other learners and post to the community library. It's not a certificate, and it won't replace an official exam, but it does reflect how you actually use the language."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "To get started at any level, read about "}, {"type": "text", "text": "how to find a language partner", "marks": [{"type": "link", "attrs": {"href": "/blog/find-a-language-exchange-partner"}}]}, {"type": "text", "text": ", or "}, {"type": "text", "text": "browse the 40 languages", "marks": [{"type": "link", "attrs": {"href": "/languages"}}]}, {"type": "text", "text": " you can practise for free."}]}]}}$j$::jsonb, true,
  $t$CEFR Levels A1 to C2 Explained: What You Can Actually Do at Each Level$t$, $t$CEFR Levels A1 to C2 Explained$t$, $t$What A1, A2, B1, B2, C1 and C2 really mean, with everyday examples for each level, how to work out your own, and how to keep moving up.$t$, $t$Language levels$t$, $t$The CEFR describes language ability on six levels, from A1 for beginners to C2 for near-native users. Each level is defined by what you can do with the language, not by how many words you know. Most learners find it most useful as a way to choose their next goal.$t$,
  $j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What the CEFR is"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "CEFR stands for the Common European Framework of Reference for Languages. It was published by the Council of Europe and is now used around the world, for many languages, by schools, employers and exam boards. It has three bands, A (basic), B (independent) and C (proficient), and each band is split in two."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The six levels, in everyday terms"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "A1: Beginner"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can introduce yourself, ask very simple questions and use common everyday phrases, if the other person speaks slowly and is willing to help. For example: \"My name is Tom. I am from Canada. I would like a coffee.\""}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "A2: Elementary"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can handle simple, routine tasks, such as shopping, asking for directions and talking about your family or job. You can write a short, simple message, though you often need to think before you say something."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "B1: Intermediate"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can get by in most situations while travelling. You can talk about your experiences, explain your plans and give simple reasons for your opinions. Many learners feel this is the point where the language starts to feel usable, and mistakes rarely stop people understanding you on familiar topics."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "B2: Upper intermediate"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can talk with native speakers fairly easily, without a lot of strain on either side. You can follow the main ideas of complex texts, argue for your point of view and work on topics in your own field. Many universities and employers look for roughly this level, but requirements vary, so check before you apply."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "C1: Advanced"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You express yourself fluently without much obvious searching for words. You can use the language flexibly for work and study, understand long and demanding texts, and write clear, well-structured documents."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "C2: Near-native"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can understand almost everything you hear or read with ease. You can summarise information from different sources and express fine shades of meaning. Most learners never need this level, and many native speakers wouldn't find a C2 exam easy."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why B1 feels so hard"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Learners often talk about the \"intermediate plateau\". In the beginning, every new word makes a visible difference. Moving from B1 to B2 takes more time, since you are now refining what you say rather than simply learning how to say it. Your progress hasn't stopped: it has just become harder to see. Regular correction helps at this stage, because you may no longer notice the errors that remain."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to work out your own level"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Read the descriptions honestly.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Pick the level where you can do almost everything comfortably, not the one you sometimes reach on a good day."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Try a free online placement test.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Use it as a rough guide, as many only test grammar and vocabulary."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Take an official exam if you need proof.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Employers and universities usually want a recognised certificate, and the exam differs from one language to another."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Remember that your skills can differ.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " It's common to read at B2 and write at A2. Our guide to "}, {"type": "text", "text": "university study in Vietnamese", "marks": [{"type": "link", "attrs": {"href": "/blog/studying-at-university-in-vietnam"}}]}, {"type": "text", "text": " shows how much this can matter."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to move up a level"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Whatever your current level, there are a few things that help:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A1 to A2:", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Learn useful sentences, and start writing short messages as soon as you can."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A2 to B1:", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Talk about your own life. Practise using past and future forms in real conversations."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "B1 to B2:", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Ask to have natural phrasing corrected, not only grammar. Read about things you already care about."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "B2 to C1:", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Work on precision. Learn the formal language of your field, and notice how native speakers structure an argument."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How levels work on The Fluency Talks"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When you join "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", you pick your level from A1 to C2 as a starting point. A separate verified level is then earned through your activity: how much you write, on how many days, whether native speakers reply to you, and how often your messages need correcting. At higher levels, the corrections you give others count too."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Once you're verified at B1 or above, you can correct other learners and post to the community library. It's not a certificate, and it won't replace an official exam, but it does reflect how you actually use the language."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "To get started at any level, read about "}, {"type": "text", "text": "how to find a language partner", "marks": [{"type": "link", "attrs": {"href": "/blog/find-a-language-exchange-partner"}}]}, {"type": "text", "text": ", or "}, {"type": "text", "text": "browse the 40 languages", "marks": [{"type": "link", "attrs": {"href": "/languages"}}]}, {"type": "text", "text": " you can practise for free."}]}]}$j$::jsonb, 4, now() - interval '6 minutes', now() - interval '6 minutes', now() - interval '6 minutes', now() - interval '6 minutes') on conflict (slug) do nothing;

insert into public.blog_posts (slug, draft, is_live, title, seo_title, description, kicker, summary, body, read_minutes, published_at, updated_at, created_at, draft_saved_at) values (
  'first-message-to-language-partner', $j${"title": "Your First Message to a Language Partner: 15 Openers That Work", "seo_title": "First Message to a Language Partner", "description": "Don't know what to say to a new language partner? Here are 15 opening messages you can adapt, what makes people reply, and the mistakes that get ignored.", "kicker": "Language exchange basics", "summary": "A good first message is short, specific and easy to answer. It says who you are, which language you're practising and something that shows you read the person's profile. Copy any of the 15 openers below and adapt it to your own situation.", "cover_url": null, "cover_alt": null, "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What makes someone reply"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Language partners get plenty of messages that only say \"hi\". A plain \"hi\" leaves all the work to them, as they have to invent a topic for you. A good opener does three things:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "It tells them who you are", "marks": [{"type": "bold"}]}, {"type": "text", "text": " and what you're learning."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "It shows why you chose them,", "marks": [{"type": "bold"}]}, {"type": "text", "text": " with one detail from their profile."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "It ends with a question that's easy to answer.", "marks": [{"type": "bold"}]}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Keep it to two to four sentences. You can tell your life story later."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "If you're a beginner"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hi, I'm Tom. I'm learning Vietnamese at A2. Can I practise with you for a few minutes a day?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hello! I'm a beginner, so my Vietnamese is slow. Is it OK if I write simple sentences and you correct me?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hi! I just started learning Spanish. How would you greet a friend in your town?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hello, I can only write short sentences so far, but I'd really like to practise. What's a phrase I should learn first?\""}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "If you'd like to swap languages"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hi, I saw you're learning English. I'm a native speaker. Shall we swap: I help with your English and you help with my Vietnamese?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hello! Your profile says you're learning French for work. I can help with that, and I'd love help with my Korean in return. Would that suit you?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hi, would you like to do half our chat in English and half in Vietnamese? What days are good for you?\""}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "If you've got something in common"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hi! I saw you live in Da Nang. I'm visiting next year. What should I eat there?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hello, you mentioned you like football. Which team do people support where you live?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hi! We're both students. What's the hardest part of your course this year?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"I noticed you like cooking. What's a dish I should try to make from your country?\""}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "If you have a specific goal"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hello, I'm preparing to study at a university in Vietnam. Could you help me write more formally?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hi, I need English for job interviews. Would you be willing to correct a few answers I've written?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hi, I write fine but I always use the same simple sentences. Could you show me how a native speaker would say them?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hello! I have one question about a sentence. Does this sound natural to you?\""}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Try it in the language you're learning"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Writing even one sentence in your target language shows effort, and it gives your partner something to correct straight away. For Vietnamese, you could try:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chào anh, em tên là Tom. Em đang học tiếng Việt.", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Hello, my name is Tom. I am learning Vietnamese. (To a man slightly older than you.)"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bạn có thể sửa giúp mình câu này không?", "marks": [{"type": "lang", "attrs": {"lang": "vi"}}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Could you help me fix this sentence?"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you're not sure which words to use for \"I\" and \"you\", see our guide to "}, {"type": "text", "text": "Vietnamese pronouns", "marks": [{"type": "link", "attrs": {"href": "/blog/vietnamese-pronouns-explained"}}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Messages to avoid"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Just \"hi\" or \"hello\".", "marks": [{"type": "bold"}]}, {"type": "text", "text": " It gives them nothing to respond to."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Asking for a lot right away.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " \"Can you check my 10-page essay?\" is too much for a first message."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Compliments about their looks.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " This is a language exchange, not a dating site. Comments like these can make people uncomfortable, and they may block you."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Asking for personal details.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Don't ask for their phone number or social media account in the first message."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pasting the same message to everyone.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " People can tell. Change at least one detail."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "If nobody answers"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Don't take it personally. People get busy, or they may not be looking for a partner this week. Send a few personalised messages rather than just one, and don't send repeated follow-ups to the same person."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What to do after they reply"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Answer soon, ask a question back, and agree how you'd like to work: how often you'll chat, and how much correcting you want. Then try saying it directly: \"Please correct me when something sounds unnatural.\" It's the single most useful sentence in a language exchange, and our guide explains "}, {"type": "text", "text": "how to get corrections from native speakers", "marks": [{"type": "link", "attrs": {"href": "/blog/corrections-from-native-speakers"}}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Sending your first message on The Fluency Talks"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "On "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", your first message arrives as a request, and the other person can accept or decline it. That's why a clear, friendly opener matters. Matches are based on language, so you'll see native speakers of your target language and people learning yours, with perfect swaps first."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Create a free account", "marks": [{"type": "link", "attrs": {"href": "/signup"}}]}, {"type": "text", "text": " and try the first opener today."}]}]}}$j$::jsonb, true,
  $t$Your First Message to a Language Partner: 15 Openers That Work$t$, $t$First Message to a Language Partner$t$, $t$Don't know what to say to a new language partner? Here are 15 opening messages you can adapt, what makes people reply, and the mistakes that get ignored.$t$, $t$Language exchange basics$t$, $t$A good first message is short, specific and easy to answer. It says who you are, which language you're practising and something that shows you read the person's profile. Copy any of the 15 openers below and adapt it to your own situation.$t$,
